package io.github.supermonster003.autojs6.plugin.three.block.compose.designer.model

import io.github.supermonster003.autojs6.plugin.three.block.compose.designer.parse.JsonText

/**
 * The native Android XML catalog (roadmap P11.3, D56 as revised by D65), generated by
 * `.python/generate_ui_catalog.py --android` from the host's attribute table and its device coverage snapshot into
 * `resources/designer-ui/catalog-android.json`: for each view class the `android:` / `app:` attributes it adds and
 * what the host's inflater does with them, the layout parameters each parent takes, and the class every tag the
 * inflater can create maps to (simple names for android.widget / android.view / android.webkit, full names else).
 */
class UiAndroidCatalog private constructor(data: Map<String, Any?>) {

    /** What the host does with an attribute: sets it, cannot set it, takes it as design-time only, or needs a newer API. */
    enum class State { SET, UNSUPPORTED, DESIGN, API }

    data class Attr(
        val name: String,
        val state: State,
        /** The first API level that has it (24 for everything the plugin's oldest Android has). */
        val since: Int,
        val formats: List<String>,
        val enums: List<String>,
        val flags: List<String>,
        /** The class that adds it; for a layout parameter the parent class whose layout takes it. */
        val ownerClass: String,
        val layoutParam: Boolean,
    )

    private class Entry(val parent: String?, val attrs: Map<String, Pair<State, Int>>)

    private class Definition(val formats: List<String>, val enums: List<String>, val flags: List<String>)

    /** The API level the coverage snapshot was taken on. */
    val coverageApi: Int = (data["coverageApi"] as Number).toInt()
    private val views: Map<String, Entry> = entries(data["views"])
    private val layouts: Map<String, Entry> = entries(data["layouts"])
    private val tags: Map<String, String> = (data["tags"] as Map<*, *>).entries.associate { it.key as String to it.value as String }
    private val definitions: Map<String, Definition> = (data["defs"] as Map<*, *>).entries.associate { (name, value) ->
        val map = value as Map<*, *>
        name as String to Definition(strings(map["f"]), strings(map["e"]), strings(map["g"]))
    }

    /** The tags the palette and the tag check know: every view class the inflater can create. */
    val tagNames: Set<String> get() = tags.keys

    /** The catalog class [tag] maps to (a simple or a full class name), or null for a class the catalog does not know. */
    fun classOf(tag: String): String? = tags[tag] ?: tag.takeIf { it in views }

    /** [className] followed by its catalog ancestors, nearest first. */
    fun chain(className: String): List<String> = generateSequence(className) { views[it]?.parent }.takeWhile { it in views }.toList()

    /** Every attribute a view of [className] takes, nearest class first, one entry per name. */
    fun attrsFor(className: String): List<Attr> {
        val seen = HashSet<String>()
        return chain(className).flatMap { owner -> attrsOf(owner, views.getValue(owner), layoutParam = false) }.filter { seen.add(it.name) }
    }

    /**
     * The layout parameters a child of [parentClass] takes: those of the nearest layout class in the parent's chain and
     * its layout ancestors (always at least ViewGroup's width, height and margins), nearest first.
     */
    fun layoutParamsFor(parentClass: String?): List<Attr> {
        val start = parentClass?.let { chain(it).firstOrNull { name -> name in layouts } } ?: VIEW_GROUP
        val seen = HashSet<String>()
        return generateSequence(start) { layouts[it]?.parent }.takeWhile { it in layouts }
            .flatMap { owner -> attrsOf(owner, layouts.getValue(owner), layoutParam = true) }.filter { seen.add(it.name) }.toList()
    }

    /** The attribute [name] of a [className] view inside a [parentClass] parent (a layout parameter when it is one), or null. */
    fun attr(className: String?, parentClass: String?, name: String): Attr? =
        (if (isLayoutParam(name)) layoutParamsFor(parentClass) else className?.let(::attrsFor).orEmpty()).firstOrNull { it.name == name }

    private fun attrsOf(owner: String, entry: Entry, layoutParam: Boolean): List<Attr> = entry.attrs.map { (name, value) ->
        val definition = definitions[name]
        Attr(name, value.first, value.second, definition?.formats.orEmpty(), definition?.enums.orEmpty(), definition?.flags.orEmpty(), owner, layoutParam)
    }

    /**
     * [attr] for the inspector's value editors: a boolean switch, an enum picker for enum-only attributes, text for the
     * rest with the formats (and the enum / flag names) as its hint.
     */
    fun toUiAttr(attr: Attr): UiCatalog.Attr {
        val formats = attr.formats.toSet()
        val type = when {
            formats == setOf("boolean") -> "boolean"
            attr.enums.isNotEmpty() && formats.all { it == "enum" || it == "integer" } -> "enum"
            formats == setOf("color") || formats == setOf("color", "reference") -> "color"
            formats == setOf("dimension") || formats == setOf("dimension", "enum") -> "dimension"
            else -> "string"
        }
        val names = (attr.enums + attr.flags).take(MAX_HINT_NAMES)
        val hint = (attr.formats.joinToString("|") + if (names.isEmpty()) "" else " (" + names.joinToString(", ") + if (attr.enums.size + attr.flags.size > names.size) ", ...)" else ")")
        return UiCatalog.Attr(attr.name, emptyList(), type, attr.enums, hint, "", if (attr.layoutParam) LAYOUT_GROUP else "", shortName(attr.ownerClass) + if (attr.layoutParam) " layout" else "")
    }

    companion object {
        const val RESOURCE = "designer-ui/catalog-android.json"
        private const val VIEW_GROUP = "android.view.ViewGroup"
        private const val LAYOUT_GROUP = "layout"
        private const val MAX_HINT_NAMES = 6

        @Volatile
        private var loaded: UiAndroidCatalog? = null

        /** The packaged catalog, read once. */
        fun load(): UiAndroidCatalog = loaded ?: synchronized(this) {
            loaded ?: parse(requireNotNull(UiAndroidCatalog::class.java.classLoader?.getResourceAsStream(RESOURCE)) { "missing $RESOURCE" }.use { String(it.readBytes(), Charsets.UTF_8) }).also { loaded = it }
        }

        @Suppress("UNCHECKED_CAST")
        fun parse(json: String): UiAndroidCatalog = UiAndroidCatalog(JsonText.parse(json) as Map<String, Any?>)

        /** `android:layout_width`, `app:layout_constraintTop_toTopOf`: the parent's layout parameters. */
        fun isLayoutParam(name: String): Boolean = name.substringAfter(':', "").startsWith("layout_")

        /** `android.widget.TextView` -> `TextView`. */
        fun shortName(className: String): String = className.substringAfterLast('.')

        private fun entries(value: Any?): Map<String, Entry> = (value as Map<*, *>).entries.associate { (name, entry) ->
            val map = entry as Map<*, *>
            name as String to Entry(map["parent"] as String?, (map["attrs"] as Map<*, *>).entries.associate { (attr, state) ->
                val parts = (state as String).split(':')
                attr as String to (State.valueOf(parts[0].uppercase()) to (parts.getOrNull(1)?.toIntOrNull() ?: 24))
            })
        }

        private fun strings(value: Any?): List<String> = (value as? List<*>)?.map { it as String }.orEmpty()
    }
}
